// Simple in-memory storage for demonstration
// In a real application, this would be a database
let posts: Post[] = [
  {
    id: '1',
    title: 'Welcome to Next.js',
    content: 'This is the first post in our blog.',
    createdAt: new Date('2024-01-01'),
    updatedAt: new Date('2024-01-01'),
  },
  {
    id: '2', 
    title: 'Server Actions Guide',
    content: 'Learn how to use Server Actions effectively.',
    createdAt: new Date('2024-01-02'),
    updatedAt: new Date('2024-01-02'),
  },
];

export interface Post {
  id: string;
  title: string;
  content: string;
  createdAt: Date;
  updatedAt: Date;
}

/**
 * Fetches all posts with caching using the 'posts' cache tag
 * This function will be cached and the cache can be invalidated
 */
export async function getPosts(): Promise<Post[]> {
  // Simulate API delay
  await new Promise(resolve => setTimeout(resolve, 500));

  return posts.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
}

/**
 * Creates a new post and invalidates the 'posts' cache
 */
export async function createPost(data: { title: string; content: string }): Promise<Post> {
  const newPost: Post = {
    id: Math.random().toString(36).substr(2, 9),
    title: data.title,
    content: data.content,
    createdAt: new Date(),
    updatedAt: new Date(),
  };

  posts.unshift(newPost);

  return newPost;
}

/**
 * Clears all posts (for testing/reset purposes)
 */
export function clearPosts() {
  posts = [];
}

'use server';

import { revalidateTag } from 'next/cache';
import { createPost, type Post } from '../lib/posts';

/**
 * Server Action to create a new post
 * This action will invalidate the 'posts' cache tag after creating the post
 * to ensure no stale data is served on subsequent page loads
 */
export async function createPostAction(formData: FormData): Promise<Post> {
  // Extract form data
  const title = formData.get('title') as string;
  const content = formData.get('content') as string;

  // Validate input
  if (!title || !content) {
    throw new Error('Title and content are required');
  }

  if (title.length < 3) {
    throw new Error('Title must be at least 3 characters long');
  }

  if (content.length < 10) {
    throw new Error('Content must be at least 10 characters long');
  }

  try {
    // Create the post
    const newPost = await createPost({ title, content });

    // Invalidate the 'posts' cache tag to ensure fresh data is fetched
    // This guarantees that the next page load will wait for fresh data
    // and not serve old cached content
    revalidateTag('posts');

    return newPost;
  } catch (error) {
    console.error('Error creating post:', error);
    throw new Error('Failed to create post');
  }
}

