import { describe, it, expect } from 'vitest';
import { createPostAction } from '../lib/actions';
import { clearPosts, getPosts } from '../lib/posts';
import { getCachedPosts } from '../app/hooks/usePosts';

describe('Post Creation with Cache Invalidation', () => {
  beforeEach(() => {
    // Clear posts before each test
    clearPosts();
  });

  it('should create a post and invalidate cache', async () => {
    // Get initial posts (will be cached)
    const initialPosts = await getCachedPosts();
    expect(initialPosts).toHaveLength(0);

    // Create a new post using the Server Action
    const newPostData = {
      title: 'Test Post',
      content: 'This is a test post content.',
    };

    // Simulate form data
    const formData = new FormData();
    formData.append('title', newPostData.title);
    formData.append('content', newPostData.content);

    const createdPost = await createPostAction(formData);

    // Verify the post was created
    expect(createdPost).toBeDefined();
    expect(createdPost.title).toBe(newPostData.title);
    expect(createdPost.content).toBe(newPostData.content);

    // Fetch posts again - this should return fresh data (not cached)
    // because the cache was invalidated by updateTag('posts')
    const updatedPosts = await getCachedPosts();
    expect(updatedPosts).toHaveLength(1);
    expect(updatedPosts[0].title).toBe(newPostData.title);
  });

  it('should validate form data', async () => {
    const formData = new FormData();
    formData.append('title', 'Hi'); // Too short
    formData.append('content', 'Valid content');

    await expect(createPostAction(formData)).rejects.toThrow(
      'Title must be at least 3 characters long'
    );
  });
});

